CREATE OR REPLACE VIEW CORE.FCT_BILLING (
    BILL_ID COMMENT 'Identifier ''bill id''. Origin: FM Business Layer.Billing.BillID',
    DATE_KEY COMMENT 'Foreign key to Date (Billing_to_Date)',
    METER_ID COMMENT 'Foreign key to Meter (Billing_to_Meter)',
    DUE_DATE COMMENT 'Attribute ''due date''. Origin: inferred from report usage (Energy_Billing_Package)',
    IS_EBILL COMMENT 'Attribute ''is e bill''. Origin: FM Business Layer.Billing.IsEBill',
    IS_OVERDUE COMMENT 'Attribute ''is overdue''. Origin: FM Business Layer.Billing.IsOverdue',
    PAYMENT_STATUS COMMENT 'Attribute ''payment status''. Origin: FM Business Layer.Billing.PaymentStatus',
    BILL_AMOUNT WITH MASKING POLICY SEC.MP_RESTRICTED_AMOUNT WITH TAG (GOV.ABAC_POLICY = 'SENSITIVE_DATA_POLICY,SENSITIVE_FINANCIAL_DATA', GOV.ACCESS_GROUP = 'BILL_AMOUNT', GOV.DATA_CLASSIFICATION = 'Restricted', GOV.SENSITIVE = 'true') COMMENT 'Measure ''bill amount''; default aggregation SUM (additive). Origin: FM Business Layer.Billing.BillAmount',
    DEMAND_CHARGE COMMENT 'Measure ''demand charge''; default aggregation SUM (additive). Origin: FM Business Layer.Billing.DemandCharge',
    ENERGY_CHARGE COMMENT 'Measure ''energy charge''; default aggregation SUM (additive). Origin: FM Business Layer.Billing.EnergyCharge',
    TAX_AMOUNT COMMENT 'Measure ''tax amount''; default aggregation SUM (additive). Origin: FM Business Layer.Billing.TaxAmount',
    TOTAL_BILL_WITH_TAX WITH MASKING POLICY SEC.MP_RESTRICTED_AMOUNT WITH TAG (GOV.ABAC_POLICY = 'SENSITIVE_FINANCIAL_DATA', GOV.ACCESS_GROUP = 'TOTAL_BILL_WITH_TAX', GOV.DATA_CLASSIFICATION = 'Restricted', GOV.SENSITIVE = 'true') COMMENT 'Measure ''total bill with tax''; default aggregation SUM (additive). Origin: FM Business Layer.Billing.TotalBillWithTax'
)
  WITH TAG (GOV.DATA_CLASSIFICATION = 'Internal - Restricted', GOV.DATA_OWNER = 'Energy Data Engineering Team', GOV.DOMAIN = 'Energy_Billing_Package', GOV.RETENTION = '7 years (FERC)')
  COMMENT = 'Fact at Billing grain. Source: CC_AND_B_PROD.BILLING. Origin: FM Business Layer.Billing'
AS
SELECT
    src.BILL_ID                                   AS BILL_ID,
    src.BILL_DATE_KEY                             AS DATE_KEY,
    src.METER_ID                                  AS METER_ID,
    src.DUE_DATE                                  AS DUE_DATE,
    src.IS_EBILL                                  AS IS_EBILL,
    IFF(src.PAYMENT_STATUS = 'Overdue', 'Yes', 'No') AS IS_OVERDUE,
    src.PAYMENT_STATUS                            AS PAYMENT_STATUS,
    src.BILL_AMOUNT                               AS BILL_AMOUNT,
    src.DEMAND_CHARGE                             AS DEMAND_CHARGE,
    src.ENERGY_CHARGE                             AS ENERGY_CHARGE,
    src.TAX_AMOUNT                                AS TAX_AMOUNT,
    src.BILL_AMOUNT + src.TAX_AMOUNT              AS TOTAL_BILL_WITH_TAX
FROM RAW_CCB.BILLING src;

